import random

def solve():
    N_TRIALS = 300000
    wins = [0] * 101

    for _ in range(N_TRIALS):
        platform = [1, 2, 3]
        next_ramp = 4

        while len(platform) == 3:
            piston = random.choice([1, 2, 3])

            if piston == 1:
                ejected = platform[0]
                wins[ejected] += 1
                p2, p3 = platform[1], platform[2]
                if next_ramp <= 100:
                    platform = [p2, p3, next_ramp]
                    next_ramp += 1
                else:
                    break
            elif piston == 2:
                ejected = platform[1]
                wins[ejected] += 1
                p3 = platform[2]
                platform = [p3]
                if next_ramp <= 100:
                    platform.append(next_ramp)
                    next_ramp += 1
                if next_ramp <= 100:
                    platform.append(next_ramp)
                    next_ramp += 1
            elif piston == 3:
                ejected = platform[2]
                wins[ejected] += 1
                p2 = platform[1]
                platform = [p2]
                if next_ramp <= 100:
                    platform.append(next_ramp)
                    next_ramp += 1
                if next_ramp <= 100:
                    platform.append(next_ramp)
                    next_ramp += 1

    probs = {i: wins[i] / N_TRIALS for i in range(1, 101)}
    sorted_balls = sorted(probs.items(), key=lambda x: x[1], reverse=True)
    print("Top balls:")
    for b, p in sorted_balls[:10]:
        print(f"Ball {b}: {p:.5f}")

solve()
